#!/usr/bin/env python3
"""Least-squares modeling and replay attacks against tags generated by RTL."""

from __future__ import annotations

import csv
import json
from pathlib import Path

import numpy as np


ROOT = Path(__file__).resolve().parents[1]
DATASET = ROOT / "results" / "rtl_auth_dataset.csv"
OUT_CSV = ROOT / "results" / "rtl_attack_results.csv"
OUT_JSON = ROOT / "results" / "rtl_attack_results.json"
TRAIN_SIZES = (100, 300, 1_000, 3_000, 10_000)


def bits(value: int, width: int) -> np.ndarray:
    return np.array([(value >> shift) & 1 for shift in range(width - 1, -1, -1)], dtype=np.uint8)


def features(rows: list[dict]) -> np.ndarray:
    binary = np.vstack(
        [np.concatenate([bits(row["challenge"], 32), bits(row["nonce"], 64)]) for row in rows]
    )
    return np.hstack([1 - 2 * binary.astype(float), np.ones((len(rows), 1))])


def tag_bits(rows: list[dict]) -> np.ndarray:
    return np.vstack([bits(row["tag"], 64) for row in rows])


def main() -> None:
    rows = []
    with DATASET.open(newline="") as handle:
        for row in csv.DictReader(handle):
            rows.append(
                {
                    "kind": int(row["kind"]),
                    "challenge": int(row["challenge"], 16),
                    "nonce": int(row["nonce"], 16),
                    "tag": int(row["tag"], 16),
                }
            )

    training = [row for row in rows if row["kind"] == 0]
    testing = [row for row in rows if row["kind"] == 1]
    fresh = [row for row in rows if row["kind"] == 2]
    if len(training) != 10_000 or len(testing) != 2_000 or len(fresh) != 2_000:
        raise RuntimeError("unexpected dataset partition sizes")

    x_test = features(testing)
    y_test = tag_bits(testing)
    results = []
    for count in TRAIN_SIZES:
        x_train = features(training[:count])
        y_train = tag_bits(training[:count])
        learned, *_ = np.linalg.lstsq(x_train, y_train.astype(float), rcond=None)
        predicted = (x_test @ learned >= 0.5).astype(np.uint8)
        exact = np.all(predicted == y_test, axis=1)
        results.append(
            {
                "training_transactions": count,
                "bit_prediction_accuracy_pct": float(100 * np.mean(predicted == y_test)),
                "full_tag_attack_success_pct": float(100 * np.mean(exact)),
                "successful_forgeries": int(np.sum(exact)),
                "test_attempts": len(testing),
            }
        )

    original_tags = np.array([row["tag"] for row in testing], dtype=np.uint64)
    fresh_nonce_tags = np.array([row["tag"] for row in fresh], dtype=np.uint64)
    replay_successes = int(np.sum(original_tags == fresh_nonce_tags))
    summary = {
        "source": "SystemVerilog RTL generated tags",
        "tag_bits": 64,
        "modeling_attack": results,
        "replay_attack": {
            "attempts": len(testing),
            "successful_replays": replay_successes,
            "success_pct": float(100 * replay_successes / len(testing)),
        },
        "ideal_random_full_tag_probability": 2.0**-64,
    }

    with OUT_CSV.open("w", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=results[0].keys())
        writer.writeheader()
        writer.writerows(results)
    OUT_JSON.write_text(json.dumps(summary, indent=2))

    print("RTL TAG ATTACK RESULTS")
    print("======================")
    print("CRPs    bit accuracy    full-tag success    forgeries")
    for result in results:
        print(
            f"{result['training_transactions']:5d}   "
            f"{result['bit_prediction_accuracy_pct']:10.3f}%   "
            f"{result['full_tag_attack_success_pct']:14.6f}%   "
            f"{result['successful_forgeries']:9d}/{result['test_attempts']}"
        )
    print(
        f"Replay with fresh nonce: {replay_successes}/{len(testing)} "
        f"({100 * replay_successes / len(testing):.6f}%)"
    )
    print(f"Ideal 64-bit random forgery probability: {2.0**-64:.3e}")


if __name__ == "__main__":
    main()
